def find_longest_substring(S):
    n = len(S)
    max_length = -1

    for i in range(n):
        for j in range(i + 1, n + 1):
            P = S[i:j]
            is_valid = True

            # Check if P is a prefix of S
            for k in range(len(P)):
                if P[k] != S[k]:
                    is_valid = False
                    break
            if is_valid:
                continue

            # Check if P is a suffix of S
            for k in range(len(P)):
                if P[k] != S[-(len(P) - k)]:
                    is_valid = False
                    break
            if is_valid:
                continue

            # Check if any non-empty substring of P is a prefix or suffix of S
            for k in range(1, len(P)):
                if S.startswith(P[:k]) or S.endswith(P[-k:]):
                    is_valid = False
                    break

            if is_valid:
                max_length = max(max_length, len(P))

    return max_length

